package com.example.transactionrecovery.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.*; import static com.example.transactionrecovery.domain.States.SagaStatus;
@Entity @Table(name="service_saga") public class Saga { @Id public UUID id; @Column(nullable=false) public UUID applicationId; @Column(nullable=false) public String tenantId; @Enumerated(EnumType.STRING) @Column(nullable=false) public SagaStatus status; @Column(nullable=false) public int compensationAttempts; @Column(nullable=false) public Instant updatedAt; protected Saga(){} public Saga(UUID id,UUID app,String tenant){this.id=id;applicationId=app;tenantId=tenant;status=SagaStatus.STARTED;updatedAt=Instant.now();} private static final Map<SagaStatus,Set<SagaStatus>> ALLOWED=Map.of(SagaStatus.STARTED,Set.of(SagaStatus.RESOURCE_ALLOCATED),SagaStatus.RESOURCE_ALLOCATED,Set.of(SagaStatus.ACTIVATING),SagaStatus.ACTIVATING,Set.of(SagaStatus.COMPLETED,SagaStatus.COMPENSATING),SagaStatus.COMPENSATING,Set.of(SagaStatus.COMPENSATED,SagaStatus.MANUAL_REQUIRED)); public void transition(SagaStatus next){if(!ALLOWED.getOrDefault(status,Set.of()).contains(next)) throw new IllegalStateException("Transition "+status+" -> "+next+" is not allowed");status=next;updatedAt=Instant.now();} }
